package com.portfoliopro.service;
import com.portfoliopro.dto.AuthDtos.*; import com.portfoliopro.model.User; import com.portfoliopro.repository.UserRepository; import com.portfoliopro.security.JwtService; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service;
@Service public class AuthService {private final UserRepository users;private final PasswordEncoder encoder;private final JwtService jwt; public AuthService(UserRepository u,PasswordEncoder e,JwtService j){users=u;encoder=e;jwt=j;}
 public AuthResponse register(RegisterRequest r){if(users.findByEmail(r.email()).isPresent())throw new RuntimeException("Email already registered"); if(r.password()==null||r.password().length()<8)throw new RuntimeException("Password must contain at least 8 characters"); User u=new User(r.name(),r.email().toLowerCase(),encoder.encode(r.password()));users.save(u);return new AuthResponse(jwt.generate(u.getEmail()),u.getName(),u.getEmail());}
 public AuthResponse login(LoginRequest r){User u=users.findByEmail(r.email().toLowerCase()).orElseThrow(()->new RuntimeException("Invalid credentials"));if(!u.isActive()||!encoder.matches(r.password(),u.getPasswordHash()))throw new RuntimeException("Invalid credentials");return new AuthResponse(jwt.generate(u.getEmail()),u.getName(),u.getEmail());}}
